            validateEdge(edge) {
                if (!edge || !edge.rate) return false;
                if (edge.rate <= 0 || edge.rate > 1e6) return false;
                if (!isFinite(edge.rate)) return false;
                return true;
            },
            validateCycle(edges) {
                let product = 1;
                for (const e of edges) { if (!this.validateEdge(e)) return false;
                    product *= e.rate; }
                if (product <= 0.5 || product > 100) return false; // suspicious cycle
                return true;
            }
        };
