        class GraphRenderer {
            constructor(canvasId) { this.canvas = document.getElementById(canvasId);
                this.ctx = this.canvas.getContext('2d');
                this.nodes = {};
                this.edges = [];
                this.highlightedPaths = [];
                this.conflictEdges = new Set();
                this.animPhase = 0;
                this.purchasePower = {};
                this.maxPower = 1;
                this.pathColors = ['#ffd700', '#ff00ff', '#00ffaa', '#ff4444', '#4488ff', '#ffaa00', '#88ff88',
                '#ff88ff'];
                this.resize();
                window.addEventListener('resize', () => this.resize()); }
            resize() { const r = this.canvas.parentElement.getBoundingClientRect();
                const w = Math.min(700, r.width - 20);
                this.canvas.width = w;
                this.canvas.height = Math.min(380, w * 0.55); }
            buildFromGraph(graph, opps, power, paths, conflictEdges) { this.nodes = {};
                this.edges = [];
                this.purchasePower = power || {};
                this.highlightedPaths = paths || [];
                this.conflictEdges = conflictEdges || new Set();
                const seen = new Set();
                this.maxPower = Math.max(1, ...Object.values(this.purchasePower)); for (const [b, tgts] of Object.entries(
                        graph)) { if (!this.nodes[b]) this.nodes[b] = { id: b, x: 0, y: 0, power: this.purchasePower[b] ||
                            0, color: this.getColor(b), oppCount: 0 }; for (const [t, e] of Object.entries(tgts)) { const k =
                            [b, t].sort().join('|'); if (!seen.has(k)) { seen.add(k);
                        this.edges.push({ from: b, to: t, vol: e.volume || 0, liq: e.liquidity || 0, rate: e.rate }); } if (
                            !this.nodes[t]) this.nodes[t] = { id: t, x: 0, y: 0, power: this.purchasePower[t] || 0,
                            color: this.getColor(t), oppCount: 0 }; } } if (opps) { for (const o of [...(opps.mega ||
                            []), ...(opps.triangular || []), ...(opps.bellman || [])]) { for (const n of o.path) { if (
                            this.nodes[n]) this.nodes[n].oppCount++; } } }
                this.forceLayout();
                this.startAnim(); }
            getColor(id) { const c = ['#ffd700', '#00f0ff', '#ff00ff', '#00ffaa', '#ff8888', '#88ff88', '#ffaa00',
                    '#aa88ff', '#ff4488', '#44ff88'
                ];
                let h = 0; for (let i = 0; i < id.length; i++) h = ((h << 5) - h) + id.charCodeAt(i); return c[Math.abs(h) %
                    c.length]; }
            forceLayout() { const nl = Object.values(this.nodes); const n = nl.length; if (!n) return; const cx = this.canvas
                    .width / 2,
                    cy = this.canvas.height / 2; const rad = Math.min(cx, cy) * 0.65;
                nl.forEach((nd, i) => { const a = (2 * Math.PI * i) / n - Math.PI / 2;
                    nd.x = cx + rad * Math.cos(a);
                    nd.y = cy + rad * Math.sin(a); }); const iters = Math.min(35, Math.max(12, n)); for (let iter = 0; iter <
                    iters; iter++) { for (let i = 0; i < n; i++) { for (let j = i + 1; j < n; j++) { const dx = nl[i].x -
                                nl[j].x,
                                dy = nl[i].y - nl[j].y; const d = Math.max(1, Math.sqrt(dx * dx + dy * dy)); const f =
                                700 / (d * d); const fx = (dx / d) * f,
                                fy = (dy / d) * f;
                            nl[i].x += fx;
