    <div id="createCoinModal" class="modal"><div class="modal-content"><h3>🪙 CREATE TOKEN</h3><input type="text" id="newCoinSymbol" placeholder="SYMBOL"><input type="number" id="newCoinPrice" value="0.000001"><input type="number" id="newCoinLiq" value="500"><button onclick="closeCreateCoinModal()">CANCEL</button><button id="createCoinBtn" class="cyan">MINT</button></div></div>
    <script>
        const audioCtx = new(window.AudioContext || window.webkitAudioContext)();

        function playTone(f, d, t = 'square', v = 0.05) { const o = audioCtx.createOscillator(),
                g = audioCtx.createGain();
            o.type = t;
            o.frequency.value = f;
            g.gain.setValueAtTime(v, audioCtx.currentTime);
            g.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + d);
            o.connect(g);
            g.connect(audioCtx.destination);
            o.start();
            o.stop(audioCtx.currentTime + d); }

        function playSpin() { playTone(800, 0.08, 'sawtooth', 0.04); }

        function playWin() { playTone(523, 0.08);
            setTimeout(() => playTone(659, 0.08), 80);
            setTimeout(() => playTone(784, 0.15), 160); }
        const canvas = document.getElementById('particleCanvas'),
            ctx = canvas.getContext('2d');
        let particles = [];

        function resize() { canvas.width = innerWidth;
            canvas.height = innerHeight; }
        window.addEventListener('resize', resize);
        resize();
        class Particle { constructor(x, y, vx, vy, c, l) { this.x = x;
                this.y = y;
                this.vx = vx;
                this.vy = vy;
                this.color = c;
                this.life = l; } }

        function anim() { ctx.clearRect(0, 0, canvas.width, canvas.height); for (let i = particles.length - 1; i >=
                0; i--) { const p = particles[i];
                p.x += p.vx;
                p.y += p.vy;
                p.vy += 0.05;
                p.life -= 0.012;
                ctx.fillStyle = p.color;
                ctx.globalAlpha = Math.max(0, p.life);
                ctx.fillRect(p.x, p.y, 3, 3); if (p.life <= 0) particles.splice(i, 1); } requestAnimationFrame(anim); }
        anim();

        function confetti(x, y, n = 25) { const cols = ['#ff00ff', '#00ff00', '#ffd700', '#00f0ff']; for (let i = 0; i <
                n; i++) particles.push(new Particle(x, y, (Math.random() - 0.5) * 7, (Math.random() - 0.5) * 6 - 3,
                cols[Math.floor(Math.random() * cols.length)], 0.5 + Math.random() * 0.4)); }
        const State = {
            bankroll: 10000,
            matrix: 0,
            level: 1,
            qFund: 0,
            lFund: 0,
            liveMode: false,
            userCoins: [],
            exchanges: {},
            allPairs: [],
            graph: {},
            triangles: [],
            opportunities: { mega: [], triangular: [], bellman: [], suspicious: [] },
            stats: { totalPairs: 0, graphNodes: 0, graphEdges: 0, triangleCount: 0, wsBytes: 0, oppCount: 0 },
            selectedIntraExchanges: new Set(),
            selectedFiats: new Set(['RUB', 'INR', 'EUR', 'GBP']),
            liveScanInterval: null,
            liveScanActive: false,
            forexRates: {},
            wsTickers: {},
            tradeLedger: [],
            proxyMode: 'direct',
            customProxyUrl: '',
            lastTradeExecTime: 0,
            lastPullTime: 0,
            graphRenderer: null,
            purchasePower: {},
            highlightedPaths: [],
            conflictEdges: new Set(),
            basketHoldings: {},
            acquisitionPaths: {},
            load() {
                try { const s = JSON.parse(localStorage.getItem('qfoam_v22final')); if (s) { this.bankroll = s
                            .bankroll || 10000;
                        this.matrix = s.matrix || 0;
                        this.level = s.level || 1;
                        this.qFund = s.qFund || 0;
                        this.lFund = s.lFund || 0;
                        this.liveMode = s.liveMode || false;
                        this.userCoins = s.userCoins || [];
                        this.selectedIntraExchanges = s.selectedIntraExchanges ? new Set(s.selectedIntraExchanges) :
                            new Set();
                        this.forexRates = s.forexRates || {};
                        this.selectedFiats = s.selectedFiats ? new Set(s.selectedFiats) : new Set();
                        this.tradeLedger = s.tradeLedger ? s.tradeLedger.slice(-15) : [];
                        this.proxyMode = s.proxyMode || 'direct';
                        this.customProxyUrl = s.customProxyUrl || '';
                        this.basketHoldings = s.basketHoldings || {};
                        this.acquisitionPaths = s.acquisitionPaths || {}; } } catch (e) {}
                document.getElementById('solAddress').value = localStorage.getItem('wallet_sol') || '';
                document.getElementById('ethAddress').value = localStorage.getItem('wallet_eth') || '';
                document.getElementById('pumpToken').value = localStorage.getItem('pumpfun_token') || '';
                document.getElementById('basketInput').value = localStorage.getItem('basket') ||
                    'USDT,BTC,ETH,DOGE,SHIB,SOL';
                document.getElementById('pathInput').value = localStorage.getItem('pathDepth') || 5;
                document.getElementById('pathSlider').value = document.getElementById('pathInput').value;
                document.getElementById('liveToggle').checked = this.liveMode;
                document.getElementById('proxySelect').value = this.proxyMode;
                document.getElementById('corsProxyUrl').value = this.customProxyUrl;
                document.getElementById('walletProxyUrl').value = localStorage.getItem('walletProxyUrl') || '';
                UI.updateProfile();
                UI.renderFiatCheckboxes();
                UI.onProxyChange();
                UI.renderTradeLedger();
                UI.applyLevelConstraints();
                updateIntraExCheckboxes();
                UI.renderBasketTracker();
            },
            save() {
                localStorage.setItem('qfoam_v22final', JSON.stringify({
                    bankroll: this.bankroll,
                    matrix: this.matrix,
                    level: this.level,
                    qFund: this.qFund,
                    lFund: this.lFund,
                    liveMode: this.liveMode,
                    userCoins: this.userCoins,
                    selectedIntraExchanges: [...this.selectedIntraExchanges],
                    forexRates: this.forexRates,
                    selectedFiats: [...this.selectedFiats],
                    tradeLedger: this.tradeLedger.slice(-15),
                    proxyMode: this.proxyMode,
                    customProxyUrl: this.customProxyUrl,
                    basketHoldings: this.basketHoldings,
                    acquisitionPaths: this.acquisitionPaths
                }));
                localStorage.setItem('wallet_sol', document.getElementById('solAddress').value);
                localStorage.setItem('wallet_eth', document.getElementById('ethAddress').value);
                localStorage.setItem('pumpfun_token', document.getElementById('pumpToken').value);
                localStorage.setItem('basket', document.getElementById('basketInput').value);
                localStorage.setItem('pathDepth', document.getElementById('pathInput').value);
                localStorage.setItem('walletProxyUrl', document.getElementById('walletProxyUrl').value);
            },
            saveWallet() { this.save(); },
            savePumpToken() { this.save(); },
            addTradeToLedger(opp, size, netProfit) {
                this.tradeLedger.unshift({ time: new Date().toISOString(), path: opp.path.join(' → '), size,
                    profit: netProfit, type: opp.type });
                if (this.tradeLedger.length > 15) this.tradeLedger.length = 15;
                this.save();
                UI.renderTradeLedger();
            },
            recordBasketPurchase(asset, amount, pathDescription) {
                if (!this.basketHoldings[asset]) this.basketHoldings[asset] = 0;
                this.basketHoldings[asset] += amount;
                if (!this.acquisitionPaths[asset]) this.acquisitionPaths[asset] = [];
                this.acquisitionPaths[asset].push({ amount, path: pathDescription, time: new Date().toISOString() });
                this.save();
                UI.renderBasketTracker();
            },
            computePurchasePower() {
                this.purchasePower = {}; if (this.bankroll <= 0) return;
                const prices = {};
                for (const pair of this.allPairs) { if (!pair.base || !pair.target) continue;
                    const ask = pair.askPrice || pair.price * 1.001; if (!prices[pair.base] || ask < prices[pair.base])
                        prices[pair.base] = ask; }
                for (const [asset, price] of Object.entries(prices)) { if (price > 0) this.purchasePower[asset] = this
                        .bankroll / price; }
                for (const stable of ['USDT', 'USD', 'USDC', 'GUSD', 'BUSD']) { if (!this.purchasePower[stable]) this
                        .purchasePower[stable] = this.bankroll; }
            },
            getTargetAssets() {
                const raw = document.getElementById('targetAssetsInput')?.value.trim();
                if (raw) return raw.split(',').map(s => s.trim().toUpperCase()).filter(Boolean);
                return document.getElementById('basketInput').value.split(',').map(s => s.trim().toUpperCase()).filter(
                    Boolean);
            },
            validateEdge(edge) { return edge && edge.rate > 0 && edge.rate < 1e6 && isFinite(edge.rate); },
            validateCycle(edges) { let p = 1; for (const e of edges) { if (!this.validateEdge(e)) return false;
