                    }
                    const profit = rt - sz;
                    if (profit < 0 && Math.abs(profit) > sz * 0.5) {
                        batchEl.innerHTML +=
                            `<div>Line ${i+1}: ${path.join(' → ')} — ⚠️ skipped (rate stale, large loss)</div>`;
                        log(`⚠️ Line ${i+1} skipped: stale rates`, 'warning');
                        continue;
                    }
