                        const endAmount = sz * (1 + opp.profitPercent / 100);
                        const price = State.getAssetPrice(startAsset);
                        if (price > 0) {
                            const acquiredAmount = endAmount / price;
                            State.recordBasketPurchase(startAsset, acquiredAmount, path.join(' → '));
                            if (!acquired[startAsset]) acquired[startAsset] = 0;
                            acquired[startAsset] += acquiredAmount;
                            if (!pathDescriptions[startAsset]) pathDescriptions[startAsset] = new Set();
                            pathDescriptions[startAsset].add(path.join(' → '));
