                    batchEl.innerHTML +=
                        `<div style="color:${profit>=0?'var(--green)':'#ff4444'}">Line ${i+1}: ${path.join(' → ')} — $${sz.toFixed(2)} → $${rt.toFixed(2)} (${profit>=0?'+':''}$${profit.toFixed(2)})</div>`;
                    log(`💸 Line ${i+1}: ${path.join(' → ')} profit $${profit.toFixed(2)}`, 'success');
                    playWin();
