                                acquired[t] += amount;
                                if (!pathDescriptions[t]) pathDescriptions[t] = new Set();
                                pathDescriptions[t].add('Reinvestment');
                                batchEl.innerHTML +=
                                    `<div>📦 ${t}: +${amount.toFixed(6)} @ $${price.toExponential(4)}</div>`;
                                log(`📦 Bought ${amount.toFixed(6)} ${t}`, 'success');
                            }
