                const r=await smartFetch('https://open.er-api.com/v6/latest/USD',{},true);
                const d=await r.json();if(!d.rates)throw new Error('Invalid');
                State.forexRates={};
                for(const cur of f){if(d.rates[cur])State.forexRates[cur]=d.rates[cur];}
                success=true;
                document.getElementById('forexStatus').textContent=`✅ ${Object.keys(State.forexRates).length} rates (ExchangeRate-API)`;
                log(`Forex: ${Object.keys(State.forexRates).length} rates`,'success');
            }catch(e){log('ExchangeRate-API failed, trying Frankfurter…','warning');}
            if(!success){try{const r=await smartFetch('https://api.frankfurter.app/latest?from=USD',{},true);const d=await r.json();if(!d.rates)throw new Error('Invalid');State.forexRates={};for(const cur of f){if(d.rates[cur])State.forexRates[cur]=1/d.rates[cur];}success=true;document.getElementById('forexStatus').textContent=`✅ ${Object.keys(State.forexRates).length} rates (Frankfurter)`;log(`Forex: ${Object.keys(State.forexRates).length} rates from Frankfurter`,'success');}catch(e){log('Frankfurter failed, using cache','error');}}
            if(!success){const fb={RUB:0.012,INR:0.012,EUR:1.08,GBP:1.26,JPY:0.0067,CNY:0.14,KRW:0.00076,AUD:0.64,CAD:0.73,CHF:1.12,AED:0.27,TRY:0.032,BRL:0.18,SGD:0.74,PLN:0.23};State.forexRates={};for(const cur of f){if(fb[cur])State.forexRates[cur]=fb[cur];}document.getElementById('forexStatus').textContent=`✅ ${Object.keys(State.forexRates).length} (cached)`;}
            State.save();displayLowValue();
        }
