                            nl[j].x -= fx;
                            nl[j].y -= fy; } } for (const e of this.edges) { const from = this.nodes[e.from],
                            to = this.nodes[e.to]; if (!from || !to) continue; const dx = to.x - from.x,
                            dy = to.y - from.y; const d = Math.max(1, Math.sqrt(dx * dx + dy * dy)); const f = d *
