                    ctx.moveTo(0, y);
                    ctx.lineTo(w, y);
                    ctx.stroke(); } const maxVol = Math.max(1, ...this.edges.map(e => e.vol || 0)); const
                    hlEdgesByPath = this.highlightedPaths.map(path => { const set = new Set(); for (let i = 0; i < path
                            .length - 1; i++) { set.add([path[i], path[i + 1]].sort().join('|')); } return set; }); for (
                        const e of this.edges) { const from = this.nodes[e.from],
                        to = this.nodes[e.to]; if (!from || !to) continue; const ek = [e.from, e.to].sort().join('|'); let
                        highlighted = false; let color = null; let isConflict = false; for (let p = 0; p < hlEdgesByPath
                            .length; p++) { if (hlEdgesByPath[p].has(ek)) { if (highlighted) { isConflict = true; break; }
                        highlighted = true;
                        color = this.pathColors[p % this.pathColors.length]; } } if (highlighted && isConflict) { ctx
                        .strokeStyle = 'rgba(255,68,68,0.8)';
