                    ctx.shadowColor = '#ff4444';
                    ctx.shadowBlur = 6; } else if (highlighted && color) { ctx.strokeStyle = color.replace(')',
                            `,${0.7+0.3*Math.sin(this.animPhase*3)})`).replace('rgb', 'rgba');
