                    ctx.setLineDash([]);
                    ctx.shadowColor = color;
                    ctx.shadowBlur = 8; } else { const alpha = Math.max(0.06, Math.min(0.45, (e.vol || 0) / maxVol));
                    ctx.strokeStyle = `rgba(0,240,255,${alpha})`;
                    ctx.lineWidth = 1;
                    ctx.setLineDash([]);
                    ctx.shadowBlur = 0; }
                ctx.beginPath();
                ctx.moveTo(from.x, from.y);
                ctx.lineTo(to.x, to.y);
                ctx.stroke();
                ctx.setLineDash([]);
                ctx.shadowBlur = 0; } for (const nd of Object.values(this.nodes)) { const inPaths = this.highlightedPaths
                        .some(p => p.includes(nd.id)); const pr = Math.min(1, (nd.power || 0) / this.maxPower); const sz =
                        7 + pr * 16; const ob = Math.min(7, (nd.oppCount || 0) * 1.8); const ts = sz + ob; const glow = ctx
                        .createRadialGradient(nd.x, nd.y, 0, nd.x, nd.y, ts * 1.7); if (inPaths) { glow.addColorStop(0,
                            'rgba(255,215,0,0.65)');
                    glow.addColorStop(0.5, 'rgba(255,215,0,0.15)');
                    glow.addColorStop(1, 'rgba(255,215,0,0)'); } else { glow.addColorStop(0, nd.color.replace(')',
                            ',0.45)').replace('rgb', 'rgba'));
                    glow.addColorStop(1, 'rgba(0,0,0,0)'); }
                ctx.fillStyle = glow;
                ctx.beginPath();
                ctx.arc(nd.x, nd.y, ts * 1.7, 0, Math.PI * 2);
                ctx.fill(); const bg = ctx.createRadialGradient(nd.x - ts * 0.25, nd.y - ts * 0.25, ts * 0.08, nd.x, nd.y,
                    ts);
                bg.addColorStop(0, '#ffffff');
                bg.addColorStop(0.3, nd.color);
                bg.addColorStop(1, '#000000');
                ctx.fillStyle = bg;
                ctx.beginPath();
