                ctx.lineWidth = inPaths ? 1.8 : 1;
                ctx.stroke();
                ctx.fillStyle = '#fff';
                ctx.font = `${Math.max(7, ts * 0.5)}px 'Courier New'`;
                ctx.textAlign = 'center';
                ctx.fillText(nd.id, nd.x, nd.y + ts + 10); } for (let p = 0; p < this.highlightedPaths.length; p++) { const
                        path = this.highlightedPaths[p]; if (path.length < 2) continue; const t = (this.animPhase + p *
                            0.3) % 1; const idx = Math.floor(t * (path.length - 1)); const nxt = Math.min(idx + 1, path
                            .length - 1); const from = this.nodes[path[idx]],
                        to = this.nodes[path[nxt]]; if (from && to) { const fr = (t * (path.length - 1)) % 1; const px = from.x +
                            (to.x - from.x) * fr,
                            py = from.y + (to.y - from.y) * fr; const color = this.pathColors[p % this.pathColors.length];
