                        this.stats.wsReconnects = s.wsReconnects || 0;
                        this.lastCoinCreateTime = s.lastCoinCreateTime || 0; } } catch (e) {}
                document.getElementById('solAddress').value = localStorage.getItem('wallet_sol') || '';
                document.getElementById('ethAddress').value = localStorage.getItem('wallet_eth') || '';
                document.getElementById('pumpToken').value = localStorage.getItem('pumpfun_token') || '';
                document.getElementById('basketInput').value = localStorage.getItem('basket') ||
                    'USDT,BTC,ETH,DOGE,SHIB,SOL';
                document.getElementById('pathInput').value = localStorage.getItem('pathDepth') || 5;
                document.getElementById('pathSlider').value = document.getElementById('pathInput').value;
                document.getElementById('liveToggle').checked = this.liveMode;
                document.getElementById('proxySelect').value = this.proxyMode;
                document.getElementById('corsProxyUrl').value = this.customProxyUrl;
                document.getElementById('execPath').value = this.execPath;
                document.getElementById('walletProxyUrl').value = localStorage.getItem('walletProxyUrl') || '';
                document.getElementById('targetAssetsInput').value = localStorage.getItem('targetAssets') || '';
                UI.updateProfile();
                UI.renderFiatCheckboxes();
                UI.onProxyChange();
                UI.renderTradeLedger();
                UI.applyLevelConstraints();
                updateIntraExCheckboxes();
                UI.renderBasketTracker();
                UI.renderBatchHistory();
                UI.updateDashboard();
            },
            save() {
                localStorage.setItem('qfoam_v22final', JSON.stringify({
                    bankroll: this.bankroll,
                    paperMatrix: this.paperMatrix,
                    liveMatrix: this.liveMatrix,
                    paperLevel: this.paperLevel,
                    liveLevel: this.liveLevel,
                    liveMode: this.liveMode,
                    userCoins: this.userCoins,
                    selectedIntraExchanges: [...this.selectedIntraExchanges],
                    forexRates: this.forexRates,
                    selectedFiats: [...this.selectedFiats],
                    tradeLedger: this.tradeLedger.slice(-50),
                    proxyMode: this.proxyMode,
                    customProxyUrl: this.customProxyUrl,
                    execPath: this.execPath,
                    basketHoldings: this.basketHoldings,
                    acquisitionPaths: this.acquisitionPaths,
                    batchHistory: this.batchHistory.slice(-20),
                    coinExchangeList: this.coinExchangeList,
                    wsReconnects: this.stats.wsReconnects,
                    lastCoinCreateTime: this.lastCoinCreateTime
                }));
                localStorage.setItem('wallet_sol', document.getElementById('solAddress').value);
                localStorage.setItem('wallet_eth', document.getElementById('ethAddress').value);
                localStorage.setItem('pumpfun_token', document.getElementById('pumpToken').value);
                localStorage.setItem('basket', document.getElementById('basketInput').value);
                localStorage.setItem('pathDepth', document.getElementById('pathInput').value);
                localStorage.setItem('walletProxyUrl', document.getElementById('walletProxyUrl').value);
                localStorage.setItem('targetAssets', document.getElementById('targetAssetsInput').value);
            },
            saveWallet() { this.save(); },
            savePumpToken() { this.save(); },
            addTradeToLedger(opp, size, netProfit) {
                this.tradeLedger.unshift({ time: new Date().toISOString(), path: opp.path.join(' → '), size,
                    profit: netProfit, type: opp.type });
                if (this.tradeLedger.length > 50) this.tradeLedger.length = 50;
                this.save();
                UI.renderTradeLedger();
                UI.updateDashboard();
            },
            recordBasketPurchase(asset, amount, pathDescription) {
                if (!this.basketHoldings[asset]) this.basketHoldings[asset] = 0;
                this.basketHoldings[asset] += amount;
                if (!this.acquisitionPaths[asset]) this.acquisitionPaths[asset] = [];
                this.acquisitionPaths[asset].push({ amount, path: pathDescription || 'unknown', time: new Date()
                        .toISOString() });
                this.save();
                UI.renderBasketTracker();
            },
            addBatchHistory(entry) {
                this.batchHistory.unshift(entry);
                if (this.batchHistory.length > 20) this.batchHistory.length = 20;
                this.save();
                UI.renderBatchHistory();
                UI.updateDashboard();
            },
            getAssetPrice(asset) {
                const stableTargets = ['USDT', 'USD', 'USDC', 'GUSD', 'BUSD'];
                for (const t of stableTargets) { const pair = this.allPairs.find(p => p.base === asset && p.target ===
                        t); if (pair) return pair.bidPrice || pair.price * 0.999; }
                const anyPair = this.allPairs.find(p => p.base === asset);
                if (anyPair) { const price = anyPair.bidPrice || anyPair.price * 0.999; if (!stableTargets.includes(
                        anyPair.target)) { const tp = this.getAssetPrice(anyPair.target); if (tp > 0) return price *
                        tp; } return price; }
                return 0;
            },
            computePurchasePower() {
                this.purchasePower = {}; if (this.bankroll <= 0) return;
                const prices = {};
                for (const pair of this.allPairs) { if (!pair.base || !pair.target) continue;
                    const ask = pair.askPrice || pair.price * 1.001; if (!prices[pair.base] || ask < prices[pair
                            .base]) prices[pair.base] = ask; }
                for (const [asset, price] of Object.entries(prices)) { if (price > 0) this.purchasePower[asset] = this
                        .bankroll / price; }
                for (const stable of ['USDT', 'USD', 'USDC', 'GUSD', 'BUSD']) { if (!this.purchasePower[stable]) this
                        .purchasePower[stable] = this.bankroll; }
            },
            getTargetAssets() { const raw = document.getElementById('targetAssetsInput')?.value.trim(); if (raw) return raw
                    .split(',').map(s => s.trim().toUpperCase()).filter(Boolean); return document.getElementById(
                        'basketInput').value.split(',').map(s => s.trim().toUpperCase()).filter(Boolean); },
            validateEdge(edge) { return edge && edge.rate > 0 && edge.rate < 1e6 && isFinite(edge.rate); },
            validateCycle(edges) { let p = 1; for (const e of edges) { if (!this.validateEdge(e)) return false;
                    p *= e.rate; } return p > 0.5 && p < 100; },
            getMaxCoinExchanges() { return Math.min(1 + Math.floor(this.level / 3), 8); },
            getCoinCooldown() { if (this.level < 5) return Infinity; return Math.max(60, 300 - (this.level - 5) *
                30); },
            getPullCooldown() { if (this.level <= 3) return 15000; if (this.level <= 6) return 12000; if (this
                    .level <= 9) return 9000; return 6000; },
            getLiveScanInterval() { if (this.level < 2) return 60000; if (this.level < 5) return 45000; if (this
                    .level < 8) return 30000; if (this.level < 10) return 15000; return 10000; },
            startAutoForex() { if (this.forexInterval) clearInterval(this.forexInterval); if (this.level >= 3 && this
                    .selectedFiats.size > 0) { document.getElementById('forexAutoStatus').textContent =
                    '🔄 Auto (5min)';
                this.forexInterval = setInterval(() => { if (!document.getElementById('scanBtn').disabled)
                        fetchForexRates(); }, 300000); } else { document.getElementById('forexAutoStatus')
                    .textContent = ''; } }
        };

        // ── PROXY & FETCH ──────────────────────────────
        const CORS_OK_EXCHANGES = new Set(['okx', 'coinbase', 'binance', 'kucoin', 'gemini', 'bitstamp', 'kraken',
            'dexscreener_eth', 'dexscreener_bsc', 'dexscreener_polygon', 'dexscreener_arb', 'dexscreener_sol',
            'coingecko', 'coinpaprika', 'coinlore'
        ]);
        const BUILTIN_PROXIES = ['https://corsproxy.io/?', 'https://api.allorigins.win/raw?url='];
        let currentProxyIndex = 0;

        function getEffectiveProxyUrl() { if (State.proxyMode === 'custom') { const c = (document.getElementById(
                    'corsProxyUrl').value || '').trim(); if (c && !c.includes('placeholder')) return c; return null; } if (
                State.proxyMode === 'builtin') return BUILTIN_PROXIES[currentProxyIndex]; return null; }

        function rotateProxy() { currentProxyIndex = (currentProxyIndex + 1) % BUILTIN_PROXIES.length;
            UI.updateProxyStatus(); }
        async function smartFetch(url, options = {}, isCorsSafe = false) { if (isCorsSafe || State.proxyMode ===
                'direct') { try { const r = await fetch(url, options); if (r.ok) return r; if (r.status >= 400) throw new
                    Error('HTTP ' + r.status); } catch (e) {} } const proxy = getEffectiveProxyUrl(); if (proxy) { try { const
                    r = await fetch(proxy + encodeURIComponent(url), options); if (!r.ok) throw new Error(
                'Proxy HTTP ' + r.status); const text = await r.text(); if (text.startsWith('<') || text.includes(
                    'corsdemo')) throw new Error('Non-JSON'); try { return new Response(JSON.stringify(JSON.parse(
                    text)), { status: 200, headers: { 'Content-Type': 'application/json' } }); } catch { return new
                Response(text, { status: 200, headers: { 'Content-Type': 'text/plain' } }); } } catch (e) { rotateProxy
            (); } } throw new Error('All fetch attempts exhausted'); }

        const KNOWN_QUOTES = ['USDT', 'USDC', 'BUSD', 'GUSD', 'USD', 'BTC', 'ETH', 'BNB', 'SOL', 'EUR', 'GBP', 'JPY',
            'KRW', 'AUD', 'CAD', 'CHF', 'RUB', 'INR', 'TRY', 'BRL', 'IDR', 'DAI', 'SGD', 'PLN', 'UAH', 'AED', 'BETH',
            'ZEC', 'ZRX', 'RAY', 'STRK', 'MATIC', 'DOT', 'TRB', 'TON', 'PI', 'LTC', 'XRP', 'SHIB', 'DOGE', 'BONK',
            'PEPE', 'FLOKI', 'WIN', 'SATS', 'NEIRO', 'CAT', 'DUCK', 'BOME', 'OMI', 'DEGEN', 'NOT', 'MEME', 'TOSHI',
            'MEW', 'HMSTR', 'XCHNG', 'WBNB', 'RNDR', 'LINK', 'JITOSOL', 'LINEA', 'HYPE', 'PNUT', 'POL', 'TRUMP',
            'POPCAT', 'CTX', 'JUP', 'GALA', 'FTM', 'FET', 'SAND', 'GRT', 'CRV', 'LTC', 'XTZ', 'SUI', 'XCH', 'AVAX',
            'WIF', 'UNI', 'FIL', 'STX', 'OP', 'TON', 'LINK', 'LPT', 'ENS', 'WLFI', 'ZEC', 'PENGU', 'APE', 'GOAT',
            'MOODENG', 'MANA', 'INJ', 'ATOM', 'AAVE', 'TRX', 'SKY', 'CHZ', 'SEI', 'ZETA', 'ARB', 'XDC', 'BONK', 'PEPE',
            'SHIB', 'FLR', 'VIRTUAL', 'NEAR', 'ADA', 'HBAR', 'API3', 'STORJ', 'IMX', 'LDO', 'MON', 'BCH', 'PUMP', 'MASK',
            'OFC', 'COMP', 'JUP', 'DOT', 'USDG', 'BAT', 'BABYDOGE', 'ALGO', 'RLUSD', 'TRAC', 'SKL', 'CTSI', 'MEW',
            'CXT', 'PYTH', 'KITE', 'DIRT', 'WOW', 'ARRR', 'TRON', 'MEME', 'UMA', 'PI', 'ZAMA', 'ETC'
        ];
        KNOWN_QUOTES.sort((a, b) => b.length - a.length);

        function parsePairSymbol(rawSymbol) { const s = (rawSymbol || '').toUpperCase().replace(/[^A-Z0-9]/g, ''); if (
                !s) return null; for (const q of KNOWN_QUOTES) { if (s.endsWith(q) && s.length > q.length) { const b = s
                        .slice(0, s.length - q.length); if (b.length >= 1 && b !== q) return { base: b, target: q }; } }
            const p = s.split(/[_-]/); if (p.length >= 2) return { base: p[0], target: p.slice(1).join('_') }; return null; }

        const exchangeDefs = [{ key: 'okx', name: 'OKX', url: 'https://www.okx.com/api/v5/market/tickers?instType=SPOT',
                parser: 'okx' }, { key: 'coinbase', name: 'Coinbase', url: 'https://api.exchange.coinbase.com/products',
                parser: 'coinbase' }, { key: 'binance', name: 'Binance', url: 'https://api.binance.com/api/v3/ticker/24hr',
                parser: 'binance' }, { key: 'kucoin', name: 'KuCoin', url: 'https://api.kucoin.com/api/v1/market/allTickers',
