                nl.forEach((nd, i) => { const a = (2 * Math.PI * i) / n - Math.PI / 2;
                    nd.x = cx + rad * Math.cos(a);
                    nd.y = cy + rad * Math.sin(a); }); const iters = Math.min(35, Math.max(12, n)); for (let iter = 0; iter <
                    iters; iter++) { for (let i = 0; i < n; i++) { for (let j = i + 1; j < n; j++) { const dx = nl[i].x -
                                nl[j].x,
                                dy = nl[i].y - nl[j].y; const d = Math.max(1, Math.sqrt(dx * dx + dy * dy)); const f =
                                700 / (d * d); const fx = (dx / d) * f,
                                fy = (dy / d) * f;
                            nl[i].x += fx;
                            nl[i].y += fy;
                            nl[j].x -= fx;
                            nl[j].y -= fy; } } for (const e of this.edges) { const from = this.nodes[e.from],
                            to = this.nodes[e.to]; if (!from || !to) continue; const dx = to.x - from.x,
                            dy = to.y - from.y; const d = Math.max(1, Math.sqrt(dx * dx + dy * dy)); const f = d *
                            0.0018; const fx = (dx / d) * f,
                            fy = (dy / d) * f;
                        from.x += fx;
                        from.y += fy;
                        to.x -= fx;
                        to.y -= fy; } for (const nd of nl) { nd.x += (cx - nd.x) * 0.018;
                        nd.y += (cy - nd.y) * 0.018;
                        nd.x = Math.max(15, Math.min(this.canvas.width - 15, nd.x));
                        nd.y = Math.max(15, Math.min(this.canvas.height - 15, nd.y)); } } }
            startAnim() { if (this.animRAF) cancelAnimationFrame(this.animRAF); const anim = () => { this.animPhase +=
