                        path = this.highlightedPaths[p]; if (path.length < 2) continue; const t = (this.animPhase + p *
                            0.3) % 1; const idx = Math.floor(t * (path.length - 1)); const nxt = Math.min(idx + 1, path
                            .length - 1); const from = this.nodes[path[idx]],
                        to = this.nodes[path[nxt]]; if (from && to) { const fr = (t * (path.length - 1)) % 1; const px = from.x +
                            (to.x - from.x) * fr,
