        function scanTriangular(minP = 0.0001) { const opps = [],
                inv = 1000; const mode = document.getElementById('arbMode').value;
            State.triangles.forEach(([A, B, C]) => { const orders = [
                    [A, B, C, A],
                    [B, C, A, B],
                    [C, A, B, C]
                ]; for (const [s, m1, m2, e] of orders) { const e1 = State.graph[s]?.[m1],
                        e2 = State.graph[m1]?.[m2],
                        e3 = State.graph[m2]?.[e]; if (!e1 || !e2 || !e3) continue; if (!State.validateCycle([e1, e2,
                            e3])) continue; if (mode === 'intra') { const exs = new Set([e1.exchange, e2.exchange,
                            e3.exchange
                        ]); if (exs.size !== 1 || !State.selectedIntraExchanges.has(e1.exchange)) continue; } const
                        final = inv * e1.rate * e2.rate * e3.rate,
                        profit = final - inv,
                        pct = (profit / inv) * 100; if (pct >= minP && pct < 50) { const ms = Math.min(e1.liquidity,
                            e2.liquidity, e3.liquidity) * 0.05;
                        opps.push({ type: 'triangular', path: [s, m1, m2, e], profitPercent: pct, actualProfit: toUsd((
                            ms / inv) * profit, s), maxTradeSize: toUsd(ms, s), edges: [e1, e2, e3] }); } } }); return opps; }

        function bellmanFord(start, depth = 5) { const cs = Object.keys(State.graph); if (!cs.includes(start)) return
            []; const mode = document.getElementById('arbMode').value; const dist = {},
                pred = {};
            cs.forEach(c => { dist[c] = Infinity;
                pred[c] = null; });
            dist[start] = 0; for (let i = 0; i < Math.min(depth - 1, cs.length - 1); i++) { let upd = false; for (const u of
                cs) { const nb = State.graph[u]; if (!nb) continue; for (const v in nb) { const w = nb[v].weight; if (
                    dist[u] !== Infinity && dist[u] + w < dist[v]) { if (mode === 'intra' && !State
                    .selectedIntraExchanges.has(nb[v].exchange)) continue;
                    dist[v] = dist[u] + w;
                    pred[v] = u;
                    upd = true; } } } if (!upd) break; } const opps = []; const target = State.getTargetAssets(); for (
                const u of cs) { const nb = State.graph[u]; if (!nb) continue; for (const v in nb) { if (dist[u] !==
                        Infinity && dist[u] + nb[v].weight < dist[v]) { const cyc = (() => { const c = [v]; let cur =
                            v; const vis = new Set();
                        vis.add(v); for (let i = 0; i < depth; i++) { cur = pred[cur]; if (!cur)
                            return null;
                            c.push(cur); if (cur === start) return c; if (vis.has(cur)) return null;
                            vis.add(cur); } return null; })(); if (cyc && cyc[0] === start && target.includes(start)) { let
                            amt = 1000; const edges = []; let tl = Infinity; for (let i = 0; i < cyc.length - 1; i++) {
                                const e = State.graph[cyc[i]]?.[cyc[i + 1]]; if (!e) break;
                            amt *= e.rate;
                            edges.push(e);
                            tl = Math.min(tl, e.liquidity); } const le = State.graph[cyc[cyc.length - 1]]?.[cyc[
                            0]]; if (le && tl >= 50 && State.validateCycle([...edges, le])) { amt *= le.rate;
                            edges.push(le);
                            tl = Math.min(tl, le.liquidity); const p = amt - 1000,
