                                    pair: ['XBT/USD', 'ETH/USD'], subscription: { name: 'ticker' } })); if (exKey ===
                                'coinbase') ws.send(JSON.stringify({ type: 'subscribe', product_ids: ['BTC-USD',
                                    'ETH-USD'
                                ], channels: ['ticker'] })); updateExchangeDisplay(); };
                        ws.onmessage = onMessage;
                        ws.onclose = () => { log(`📡 ${exKey} WS disconnected, reconnecting in ${retryDelay/1000}s…`,
