                            vis.add(cur); } return null; })(); if (cyc && cyc[0] === start && target.includes(start)) { let
                            amt = 1000; const edges = []; let tl = Infinity; for (let i = 0; i < cyc.length - 1; i++) {
                                const e = State.graph[cyc[i]]?.[cyc[i + 1]]; if (!e) break;
                            amt *= e.rate;
